<?php
declare(strict_types=1);
$APP_CONFIG=require dirname(__DIR__).'/config.php';
define('PROJECT_ROOT',(string)$APP_CONFIG['storage']['project_root']);
define('MAX_IMAGE_BYTES',(int)$APP_CONFIG['limits']['max_image_bytes']);
define('MAX_AUDIO_BYTES',(int)$APP_CONFIG['limits']['max_audio_bytes']);
function app_config(?string $section=null):mixed{global $APP_CONFIG;return $section===null?$APP_CONFIG:($APP_CONFIG[$section]??null);}
function respond(int $status,array $payload):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');echo json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
if(!is_dir(PROJECT_ROOT)&&!mkdir(PROJECT_ROOT,0750,true)&&!is_dir(PROJECT_ROOT)){respond(503,['error'=>'作品存储目录无法创建，请检查服务端写入权限']);}
if(!is_writable(PROJECT_ROOT)){respond(503,['error'=>'作品存储目录不可写，请检查服务端权限']);}
function request_ip():string{$s=app_config('security');$raw=!empty($s['trust_proxy'])?($_SERVER['HTTP_X_FORWARDED_FOR']??$_SERVER['REMOTE_ADDR']??'unknown'):($_SERVER['REMOTE_ADDR']??'unknown');$ip=trim(explode(',',$raw)[0]);return filter_var($ip,FILTER_VALIDATE_IP)?$ip:'unknown';}
function requester_owner_hash():string{$s=app_config('security');return hash_hmac('sha256',request_ip(),(string)$s['ip_hash_key']);}
function project_owned_by_requester(array $project):bool{$stored=(string)($project['ownerIpHash']??'');return $stored!==''&&hash_equals($stored,requester_owner_hash());}
function start_admin_session():void{if(session_status()===PHP_SESSION_ACTIVE)return;session_name('ZZLMVPSESSID');session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','httponly'=>true,'samesite'=>'Strict']);session_start();}
function admin_authenticated():bool{start_admin_session();$a=app_config('admin');return !empty($_SESSION[(string)$a['session_key']]);}
function can_edit_project(array $p):bool{return project_owned_by_requester($p)||admin_authenticated();}
function safe_id(?string $v):?string{return is_string($v)&&preg_match('/^[a-z0-9]{10,20}$/',$v)?$v:null;}
function make_id():string{return strtolower(rtrim(strtr(base64_encode(random_bytes(9)),'+/','az'),'='));}
function project_path(string $id):string{return PROJECT_ROOT.'/'.$id;}
function read_project_file(string $id):?array{$f=project_path($id).'/project.json';if(!is_file($f))return null;$d=json_decode((string)file_get_contents($f),true);return is_array($d)?$d:null;}
function project_counts(string $owner):array{$total=0;$owned=0;foreach(glob(PROJECT_ROOT.'/*',GLOB_ONLYDIR)?:[] as $dir){$id=basename($dir);if(!safe_id($id))continue;$p=read_project_file($id);if(!$p)continue;$total++;if(!empty($p['ownerIpHash'])&&hash_equals((string)$p['ownerIpHash'],$owner))$owned++;}return ['total'=>$total,'owned'=>$owned];}
function project_views(string $id):int{$f=project_path($id).'/views.txt';return is_file($f)?max(0,(int)trim((string)file_get_contents($f))):0;}
function increment_project_views(string $id):int{$f=project_path($id).'/views.txt';$h=@fopen($f,'c+');if(!$h)return project_views($id);$v=0;if(flock($h,LOCK_EX)){rewind($h);$v=max(0,(int)trim((string)stream_get_contents($h)))+1;rewind($h);ftruncate($h,0);fwrite($h,(string)$v);fflush($h);flock($h,LOCK_UN);}fclose($h);return $v;}
function write_json_atomic(string $file,array $data):void{$tmp=$file.'.tmp-'.bin2hex(random_bytes(3));$json=json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT);if($json===false||file_put_contents($tmp,$json,LOCK_EX)===false||!rename($tmp,$file)){@unlink($tmp);throw new RuntimeException('作品文件写入失败');}}
function delete_project_directory(string $id):void{$dir=project_path($id);if(!is_dir($dir))throw new RuntimeException('没有找到要删除的作品');foreach(new FilesystemIterator($dir,FilesystemIterator::SKIP_DOTS) as $e){if(!$e->isFile()&&!$e->isLink())throw new RuntimeException('作品目录包含异常内容，已停止删除');if(!@unlink($e->getPathname()))throw new RuntimeException('作品文件删除失败');}if(!@rmdir($dir))throw new RuntimeException('作品目录删除失败');}
function clean_config(string $raw):array{if(strlen($raw)>30000)respond(400,['error'=>'配置内容过大']);$in=json_decode($raw,true);if(!is_array($in))respond(400,['error'=>'配置格式无效']);$locale=in_array($in['locale']??'', ['zh-CN','zh-TW','en'],true)?$in['locale']:'zh-CN';$demo=['zh-CN'=>['夏夜知了','一转，就听见夏天','single',['哇','呀','嗡','鸣','知']], 'zh-TW'=>['夏夜知了','一轉，就聽見夏天','single',['哇','呀','嗡','鳴','知']], 'en'=>['Summer Cicada','Spin it and hear the sound of summer','phrase',['BUZZ','WHIRR','HUM','CHIRP','SING']]][$locale];$mode=in_array($in['echoMode']??'', ['single','phrase'],true)?$in['echoMode']:$demo[2];$rawEcho=is_array($in['echoes']??null)?$in['echoes']:(isset($in['echo'])?[$in['echo']]:$demo[3]);$echoes=[];foreach(array_slice($rawEcho,0,12) as $v){if(!is_string($v))continue;$v=trim(preg_replace('/[\x00-\x1f\x7f]/u','',$v)??'');if($v!=='')$echoes[]=mb_substr($v,0,$mode==='single'?1:30);}if(!$echoes)$echoes=$demo[3];$text=static function($v,$max,$fallback){if(!is_string($v))return $fallback;$v=trim(preg_replace('/[\x00-\x1f\x7f]/u','',$v)??'');return mb_substr($v,0,$max)?:$fallback;};$color=static fn($v,$f)=>is_string($v)&&preg_match('/^#[0-9a-f]{6}$/i',$v)?strtolower($v):$f;$num=static fn($v,$min,$max,$f)=>is_numeric($v)?max($min,min($max,(float)$v)):$f;return ['locale'=>$locale,'title'=>$text($in['title']??'',30,$demo[0]),'subtitle'=>$text($in['subtitle']??'',50,$demo[1]),'echo'=>$echoes[0],'echoMode'=>$mode,'echoes'=>$echoes,'accent'=>$color($in['accent']??null,'#e76543'),'background'=>$color($in['background']??null,'#09152a'),'size'=>$num($in['size']??null,70,180,112),'speed'=>$num($in['speed']??null,.2,3.5,1.2),'radius'=>$num($in['radius']??null,30,130,70),'rope'=>$num($in['rope']??null,80,240,155),'volume'=>$num($in['volume']??null,0,1,.75),'createdAt'=>date(DATE_ATOM)];}
function base_url():string{$proto=($_SERVER['HTTP_X_FORWARDED_PROTO']??'')==='https'||(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$host=preg_replace('/[^a-z0-9.\-:\[\]]/i','',$_SERVER['HTTP_HOST']??'localhost');$path=getenv('APP_BASE_PATH');$script=str_replace('\\','/',(string)($_SERVER['SCRIPT_NAME']??'/api/project.php'));$base=$path!==false&&$path!==''?$path:dirname(dirname($script));$base='/'.trim((string)preg_replace('#[^a-z0-9/_\-.~]#i','',$base),'/');if($base==='/'||$base==='/.')$base='';return $proto.'://'.$host.$base;}
